    @Test
    fun `tile and in-tile pixel match the validated prototype`() {
        for (v in vectors) {
            val s = Healpix.tileSample(v.order, v.ra, v.dec)
            assertEquals("npix for $v", v.npix, s.npix)
            assertEquals("col for $v", v.col, s.col)
            assertEquals("row for $v", v.row, s.row)
        }
    }

    @Test
    fun `order 0 faces follow the HEALPix layout`() {
        // north cap faces 0..3, equatorial 4..7, south cap 8..11
        assertTrue(Healpix.tileSample(0, 45.0, 80.0).npix in 0..3)
        assertEquals(4, Healpix.tileSample(0, 0.0, 0.0).npix)
        assertTrue(Healpix.tileSample(0, 45.0, -80.0).npix in 8..11)
    }

    @Test
    fun `tile path and counts`() {
        assertEquals("Norder3/Dir0/Npix10.jpg", Healpix.tilePath(3, 10))
        assertEquals("Norder6/Dir40000/Npix40123.jpg", Healpix.tilePath(6, 40123))
        assertEquals(12, Healpix.tileCount(0))
        assertEquals(12288, Healpix.tileCount(5))
        assertEquals(58.63 / 512, Healpix.tilePixelDeg(0), 0.001)
    }

    @Test
    fun `TAN centre pixel maps to the field centre, east is left`() {
        val (ra, dec) = Healpix.tanToSky(56.75, 24.1, 2.0, 101, 50, 50)
        assertEquals(56.75, ra, 1e-9)
        assertEquals(24.1, dec, 1e-9)
        val (raLeft, _) = Healpix.tanToSky(56.75, 24.1, 2.0, 101, 0, 50)
        assertTrue("RA grows to the left", raLeft > 56.75)
        val (_, decTop) = Healpix.tanToSky(56.75, 24.1, 2.0, 101, 50, 0)
        assertTrue("north is up", decTop > 24.1)
    }
}
